    //==================================================================================================

    /// range_set cardinality equals range size.
    pub proof fn lemma_range_set_len(lo: int, hi: int)
        requires
            lo <= hi,
        ensures
            BitmapView::range_set(lo, hi).len() == hi - lo,
    {
        vstd::set_lib::lemma_int_range(lo, hi);
